let state={counts:{},shinyCounts:{},appearance:{},historyShiny:[],history:[],name:'Dresseur',zone:'route',team:[],xp:{},training:{},moves:{},money:0,inv:defaultInv(),kills:{},traits:{},badges:{},autoOn:false,reducedMotion:false},busy=false,shopId='jade',view='',lastRoll=0;
try{const s=JSON.parse(localStorage.getItem(saveKey));if(s&&typeof s==='object'){if(s.counts&&typeof s.counts==='object')state.counts=Object.fromEntries(Object.entries(s.counts).filter(([id,n])=>pool.some(p=>p.id===+id)&&Number.isSafeInteger(n)&&n>0));if(Array.isArray(s.history)){const recent=s.history.map((id,i)=>({id,shiny:s.historyShiny?.[i]===true})).filter(item=>pool.some(p=>p.id===item.id)).slice(0,5);state.history=recent.map(item=>item.id);state.historyShiny=recent.map(item=>item.shiny);}state.money=sanitizeMoney(s.money);state.inv=sanitizeInv(s.inv);state.autoOn=s.autoOn===true&&state.inv.owned.auto===true;state.kills=sanitizeKills(s.kills);state.traits=sanitizeTraits(s.traits);state.badges=sanitizeBadges(s.badges);if(typeof s.name==='string')state.name=s.name.slice(0,24)||'Dresseur';if(zones.some(z=>z.id===s.zone))state.zone=s.zone;state.reducedMotion=!!s.reducedMotion;if(s.moves&&typeof s.moves==='object'&&!Array.isArray(s.moves))state.moves=Object.fromEntries(Object.entries(s.moves).filter(([id,r])=>pool.some(p=>p.id===+id)&&Array.isArray(r?.known)&&r.known.length>0&&r.known.length<=4&&r.known.every(n=>typeof n==='string'&&/^[a-z0-9-]{1,40}$/.test(n))&&Number.isInteger(r.seen)).map(([id,r])=>[id,{known:[...r.known],seen:r.seen}]));Object.assign(state,migrateShinies(state.counts,s.shinyCounts,s.appearance));if(s.training&&typeof s.training==='object'&&!Array.isArray(s.training))state.training=s.training;if(s.xp&&typeof s.xp==='object'&&!Array.isArray(s.xp))state.xp=Object.fromEntries(Object.entries(s.xp).filter(([id,n])=>state.counts[id]&&Number.isSafeInteger(n)&&n>0));if(Array.isArray(s.team))state.team=dedupeLines([...new Set(s.team.filter(id=>state.counts[id]&&pool.some(p=>p.id===id)))]).slice(0,6);else state.team=pool.filter(p=>state.counts[p.id]).sort((a,b)=>powers[b.id-1]-powers[a.id-1]).reduce((team,p)=>teamAfterCapture(team,p.id),[]);}}catch{}
