const lv=id=>levelInfo(id,state.counts[id]||1,state.xp[id]||0),boostOf=id=>selectedShiny(state,id)?SHINY_BOOST:1,multsOf=id=>{const sh=boostOf(id),h=statMultipliers(state.inv,id);return Object.fromEntries(STAT_KEYS.map(k=>[k,sh*(h[k]||1)]));},powerOf=id=>Math.round(powerAt(id,lv(id).level)*boostOf(id)*powerMultiplier(state.inv,id));
