 body.innerHTML=`<div class="arena"><div class="arena-hero"><img class="arena-trainer" src="${a.sprite}" alt="${a.leader}" onerror="this.style.visibility='hidden'"><div class="arena-who"><span class="arena-type">Arène ${a.type} · ${a.city}</span><h3>${a.title}</h3><p class="arena-quote">« ${a.quote} »</p></div><span class="arena-badge${won?' won':''}"><img src="${a.badgeSprite}" alt=""><b>${a.badgeName}</b><small>${won?'Obtenu ✓':'À gagner'}</small></span></div><div class="arena-team">${a.team.map(([id,l])=>`<div class="arena-mon"><img src="${sprite(id,false)}" alt=""><b>${pool[id-1].name}</b><small>Niv. ${l}</small></div>`).join('')}</div><p class="arena-rules">${a.team.length} Pokémon · niveau ${a.ace} au maximum · pas de fuite · les objets du sac sont autorisés. Niveau conseillé : ${a.need}+.</p><p class="arena-reward">${won?'Revanche : ':'Récompense : '}<b>${fmtMoney(arenaPrize(a,!won))}</b>${won?'':' + <b>'+ITEMS[a.tm].name+'</b>'}</p><button class="arena-go" id="arena-go" ${acc.ok&&state.team.length?'':'disabled'}>${acc.ok?(won?'Revanche contre '+a.leader:'Défier '+a.leader):lockText(acc)}</button></div>`;
