async function startArena(id){const a=arenaById(id);if(busy||!a||!state.team.length)return;const acc=arenaAccess(a,leadLevel(),state.badges);if(!acc.ok){mapNote(lockText(acc));return;}if($('#content-dialog').open)$('#content-dialog').close();busy=true;await learnAll();fight.cancel();lastRoll++;busy=false;$('#roll').hidden=true;$('#result').hidden=false;$('#result-name').hidden=false;$('#result-details').hidden=false;$('#result-details').textContent=`${a.title} · ${a.team.length} Pokémon`;$('#hp').hidden=false;$('#stage').classList.remove('rolling');$('#stage-caption').textContent='ARÈNE · PAS DE FUITE';$('#roll-cta').textContent='Combat d’arène en cours';$('#roll-cta').disabled=true;fight.startBoss(a);}
