function openView(next){$('#content-dialog').classList.toggle('catalog-mode',next==='pokemon'||next==='zone');$('#content-dialog').classList.toggle('settings-mode',next==='settings');$('#content-dialog').classList.toggle('shop-mode',next==='shop'||next==='items');profileToken++;$('#content-dialog').classList.remove('profile-mode');if($('#menu-drawer').open)$('#menu-drawer').close();view=next;$('#modal-title').textContent={power:'Rangs de puissance',shop:shopById(shopId).name,items:'Objets actifs',pokemon:'Mes Pokémon',map:'Carte de Kanto',history:'Dernières rencontres',odds:'Probabilités',settings:'Paramètres',arena:arenaById(arenaId).leader,zone:'Index · '+zones.find(z=>z.id===state.zone).name}[view];$('#modal-kicker').textContent={power:'TON ÉQUIPE · TES PALIERS',shop:'POKÉMART · KANTO',items:'TON SAC · EFFETS ACTIFS',pokemon:'TA COLLECTION · TON ÉQUIPE',map:'KANTO · GÉNÉRATION I',history:'LES CINQ DERNIERS TIRAGES',odds:'KANTO · '+zones.find(z=>z.id===state.zone).name.toUpperCase(),settings:'FAÇONNE TON AVENTURE',arena:'ARÈNE · '+arenaById(arenaId).city.toUpperCase(),zone:'POKÉMON PRÉSENTS · KANTO'}[view];const body=$('#modal-body');if(view==='power'){renderPowerRanks();}else if(view==='pokemon'){collectionView=mountCollection(body,{getState:()=>state,level:lv,power:powerOf,onTeam(team){state.team=team;save();render();},onProfile:openProfile});}else if(view==='shop'){shopView=mountShop(body,{getState:()=>state,shopId,onChange(){applyInventory();save();render();renderZones();}});}else if(view==='items'){mountItems(body,{getState:()=>state,onChange(){applyInventory();save();render();}});}else if(view==='map'){body.innerHTML='<label for="region-select">Région</label><select class="regions" id="region-select"><option>Kanto — Génération I</option><option disabled>Johto — Génération II · à venir</option><option disabled>Hoenn — Génération III · à venir</option><option disabled>Sinnoh — Génération IV · à venir</option><option disabled>Unys — Génération V · à venir</option><option disabled>Kalos — Génération VI · à venir</option><option disabled>Alola — Génération VII · à venir</option><option disabled>Galar — Génération VIII · à venir</option><option disabled>Paldea — Génération IX · à venir</option></select><div class="large-map">'+mapMarkup(state.zone,busy,shopStates())+'</div><p class="map-instructions">Clique sur un rond lumineux pour voyager. Les noms apparaissent au survol ou au clavier.</p>';}else if(view==='zone'){zoneView=mountZoneIndex(body,{getState:()=>state,bonus:()=>rarityBonus(state.inv),getZone:()=>zones.find(z=>z.id===state.zone),onProfile:openProfile});}else if(view==='arena'){renderArena(body);}else if(view==='history'){body.innerHTML='<div id="history"></div>';renderHistory();}else if(view==='odds'){body.innerHTML='<p>Chances actuelles du prototype, encore provisoires. Les améliorations, les légendaires à 1 sur 500 millions et les renaissances ne sont pas encore implémentés.</p><p>Une espèce ayant au moins un type favorisé reçoit un poids ×3, puis toutes les chances sont recalculées pour totaliser 100 %. Cela ne signifie pas que sa probabilité finale est multipliée exactement par trois.</p>'+zonePool(state.zone).sort((a,b)=>b.probability-a.probability).map(p=>`<div class="odds-row"><img src="${ownedSprite(p.id)}" alt=""><span>${p.name}</span><small>${odds(p)}</small><b>${(p.probability*100).toLocaleString('fr-FR',{maximumFractionDigits:2})} %</b></div>`).join('');}else{mountSettings(body,{getName:()=>state.name,onName(name){state.name=name;save();render();},onPreferences(p){state.reducedMotion=p.reducedMotion;applyPreferences();save();render();}});}if(!$('#content-dialog').open)$('#content-dialog').showModal();}
const shopStates=()=>SHOPS.map(s=>({id:s.id,x:s.at.x,y:s.at.y,name:s.name,open:shopOpen(state.kills,s),kills:shopKills(state.kills,s),need:KILLS_TO_UNLOCK,after:s.after}));
function applyInventory(){setShinyDenominator(shinyDenominator(state.inv));if(!state.inv.owned.auto)state.autoOn=false;renderAuto();}
// Mode Auto : bouton sous la zone, lance les rencontres et joue les tours seul (pause si une fenêtre est ouverte).
function renderAuto(){const b=$('#auto-toggle');if(!b)return;const owned=!!state.inv.owned.auto;b.hidden=!owned;b.setAttribute('aria-pressed',String(owned&&state.autoOn));$('#auto-state').textContent=state.autoOn?'ON':'OFF';b.classList.toggle('on',owned&&state.autoOn);}
// Tourne en continu, même menu, paramètres ou boutique ouverts ; seul un choix d'attaque à oublier le met en attente.
function autoTick(){if(!state.autoOn||!state.inv.owned.auto||!state.team.length)return;if(document.querySelector('dialog.learn[open]')||busy||learning)return;if(fight.autoStep()==='idle')roll({auto:true});}
setInterval(autoTick,650);
let shopView=null;const renderShops=()=>{renderZones();if(view==='shop'&&$('#content-dialog').open)shopView?.refresh();};
function renderZoneIndex(){zoneView?.refresh();}
function renderDex(){collectionView?.refresh();}
$('#modal-body').addEventListener('click',e=>{const appearance=e.target.closest('[data-appearance]');if(appearance){const id=+appearance.dataset.id,shiny=appearance.dataset.appearance==='shiny';if(!formCount(state,id,shiny))return;state.appearance[id]=shiny?'shiny':'normal';resetEncounter();save();render();openProfile(id,shiny);return;}const pr=e.target.closest('[data-profile]');if(pr){openProfile(+pr.dataset.profile);return;}const lead=e.target.closest('[data-lead]');if(lead){const id=+lead.dataset.lead;state.team=[id,...state.team.filter(n=>n!==id)];save();render();openProfile(id);return;}const hr=e.target.closest('[data-held-remove]');if(hr){const pid=+hr.closest('.pf').dataset.id;if(unequipHeld(state,pid,hr.dataset.heldRemove)){save();render();openProfile(pid);}return;}const ha=e.target.closest('[data-held-add]');if(ha){pickHeld(+ha.dataset.heldAdd);return;}const ut=e.target.closest('[data-use-tm]');if(ut){pickTm(+ut.dataset.useTm);return;}if(e.target.closest('[data-close]')){$('#content-dialog').close();return;}if(e.target.closest('[data-back]')){openView('pokemon');return;}const b=e.target.closest('[data-equip]');if(!b)return;const id=+b.dataset.equip;if(state.team.includes(id))state.team=state.team.filter(n=>n!==id);else if(state.counts[id])state.team=teamAfterEquip(state.team,id);save();render();if(view==='profile')openProfile(id);else renderDex();});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>openView(b.dataset.view));$('#team-shortcut').onclick=()=>openView('pokemon');$('#items-button').onclick=()=>openView('items');$('#auto-toggle').onclick=()=>{if(!state.inv.owned.auto)return;state.autoOn=!state.autoOn;save();renderAuto();if(state.autoOn)autoTick();};renderAuto();let dragged=false;
(function(){const grid=$('#team-grid');let d=null;
// Glisser-déposer : la vraie carte suit le pointeur, les autres glissent pour lui faire de la place.
const cards=()=>[...grid.children].filter(c=>c.matches('.team-card[data-profile]'));
const place=()=>{const n=d.cards.length,order=d.cards.filter(c=>c!==d.c);order.splice(d.to,0,d.c);order.forEach((c,slot)=>{if(c===d.c)return;const a=d.rects[d.cards.indexOf(c)],b=d.rects[slot];c.style.transform=`translate(${b.left-a.left}px,${b.top-a.top}px)`;});};
const clear=()=>{if(!d)return;d.cards.forEach(c=>{c.classList.remove('dragging','sliding','settle');c.style.transform='';c.style.willChange='';c.style.transition='';c.style.zIndex='';});grid.classList.remove('is-dragging');document.body.classList.remove('team-dragging');clearTimeout(d.t);d=null;};
grid.addEventListener('pointerdown',e=>{if(d)return;const c=e.target.closest('.team-card[data-profile]');if(!c||(e.pointerType==='mouse'&&e.button!==0))return;const cs=cards();d={c,cards:cs,from:cs.indexOf(c),to:cs.indexOf(c),x:e.clientX,y:e.clientY,on:false,id:e.pointerId};});
let raf=0,last=null;window.addEventListener('pointermove',e=>{if(!d||d.settling||e.pointerId!==d.id)return;last=e;if(d.on&&raf)return;if(d.on){raf=requestAnimationFrame(()=>{raf=0;if(d&&d.on&&!d.settling)move(last);});return;}move(e);});
function move(e){
 if(!d.on){if(Math.hypot(e.clientX-d.x,e.clientY-d.y)<8)return;d.on=true;d.rects=d.cards.map(c=>c.getBoundingClientRect());d.cards.forEach(c=>{c.style.willChange='transform';if(c!==d.c)c.classList.add('sliding');});d.c.classList.add('dragging');grid.classList.add('is-dragging');document.body.classList.add('team-dragging');}
 const dx=e.clientX-d.x,dy=e.clientY-d.y;d.c.style.transform=`translate(${dx}px,${dy}px) scale(1.06) rotate(${Math.max(-6,Math.min(6,dx/40))}deg)`;
 const r0=d.rects[d.from],cx=r0.left+r0.width/2+dx,cy=r0.top+r0.height/2+dy;let best=d.to,bd=Infinity;d.rects.forEach((r,k)=>{if(k>=d.cards.length)return;const dd=Math.hypot(cx-(r.left+r.width/2),cy-(r.top+r.height/2));if(dd<bd){bd=dd;best=k;}});
 if(best!==d.to){d.to=best;place();}}
const end=e=>{if(!d||d.settling||e.pointerId!==d.id)return;if(!d.on){clear();return;}
 dragged=true;setTimeout(()=>{dragged=false;},50);
 if(e.type!=='pointerup'||d.to===d.from){d.c.classList.add('settle');d.c.style.transform='';d.cards.forEach(c=>{if(c!==d.c)c.style.transform='';});const cur=d;d.settling=true;d.t=setTimeout(()=>{if(d===cur)clear();},260);return;}
 const t=d.rects[d.to],a=d.rects[d.from],cur=d;d.settling=true;d.c.classList.add('settle');d.c.style.transform=`translate(${t.left-a.left}px,${t.top-a.top}px)`;
 d.t=setTimeout(()=>{if(d!==cur)return;const [id]=state.team.splice(cur.from,1);state.team.splice(cur.to,0,id);
  const order=cur.cards.filter(c=>c!==cur.c);order.splice(cur.to,0,cur.c);cur.cards.forEach(c=>{c.style.transition='none';c.style.transform='';});order.forEach(c=>grid.insertBefore(c,grid.querySelector('.team-card.empty')));
  order.forEach((c,i)=>{c.classList.toggle('lead',i===0);const t=c.querySelector('.tc-tags');if(t)t.innerHTML=(i===0?'<i class="lead-tag">EN TÊTE</i>':'<i class="slot-no">'+(i+1)+'</i>')+'<i class="grip"><b></b><b></b><b></b><b></b><b></b><b></b></i>';});
  save();clear();grid.dataset.keep='1';render();},230);};
window.addEventListener('pointerup',end);window.addEventListener('pointercancel',end);window.addEventListener('blur',()=>{if(d&&!d.settling)clear();});})();
$('#team-grid').onclick=e=>{if(dragged)return;const c=e.target.closest('[data-profile]');if(c)openProfile(+c.dataset.profile);else openView('pokemon');};$('#power-widget').onclick=()=>openView('power');$('#edit-profile').onclick=()=>openView('settings');$('#open-zone-index').onclick=()=>openView('zone');$('#expand-map').onclick=()=>openView('map');state.reducedMotion=getPreferences().reducedMotion;applyPreferences();save();render();

